function readWavChannels(file) {
  const buf = fs.readFileSync(file);
  let pos = 12;
  let fmt = null;
  while (pos + 8 <= buf.length) {
    const id = buf.toString('ascii', pos, pos + 4);
    const size = buf.readUInt32LE(pos + 4);
    const at = pos + 8;
    if (id === 'fmt ') {
      let tag = buf.readUInt16LE(at);
      if (tag === 0xfffe && size >= 26) tag = buf.readUInt16LE(at + 24);
      fmt = { tag, channels: buf.readUInt16LE(at + 2), rate: buf.readUInt32LE(at + 4), bits: buf.readUInt16LE(at + 14) };
    }
    if (id === 'data' && fmt) {
      const bytes = fmt.bits / 8;
      const frames = Math.floor(Math.min(size, buf.length - at) / (bytes * fmt.channels));
      const out = [];
      for (let c = 0; c < fmt.channels; c++) out.push(new Float64Array(frames));
      for (let i = 0; i < frames; i++) {
        for (let c = 0; c < fmt.channels; c++) {
          const o = at + (i * fmt.channels + c) * bytes;
          let v;
          if (fmt.tag === 3) v = bytes === 8 ? buf.readDoubleLE(o) : buf.readFloatLE(o);
          else if (bytes === 2) v = buf.readInt16LE(o) / 32768;
          else if (bytes === 3) v = buf.readIntLE(o, 3) / 8388608;
          else if (bytes === 4) v = buf.readInt32LE(o) / 2147483648;
          else throw new Error('unsupported sample size');
          out[c][i] = v;
        }
      }
      return { rate: fmt.rate, channels: out };
    }
    pos = at + size + (size % 2);
  }
  throw new Error('not a readable WAV file');
}

// Lead vocals live roughly between 200 Hz and 7 kHz; below that are kick and bass, above it air.
// [start of fade-in, fully in, fully in until, end of fade-out] in Hz.
const VOCAL_BAND = [140, 260, 6500, 9000];

function fft(re, im, inverse) {
  const n = re.length;
  for (let i = 1, j = 0; i < n; i++) {
    let bit = n >> 1;
    for (; j & bit; bit >>= 1) j ^= bit;
    j ^= bit;
    if (i < j) { let t = re[i]; re[i] = re[j]; re[j] = t; t = im[i]; im[i] = im[j]; im[j] = t; }
  }
  for (let len = 2; len <= n; len <<= 1) {
    const ang = (inverse ? 2 : -2) * Math.PI / len;
    const wr = Math.cos(ang);
    const wi = Math.sin(ang);
    for (let i = 0; i < n; i += len) {
      let cr = 1;
      let ci = 0;
      for (let k = 0; k < len / 2; k++) {
        const ur = re[i + k];
        const ui = im[i + k];
        const vr = re[i + k + len / 2] * cr - im[i + k + len / 2] * ci;
        const vi = re[i + k + len / 2] * ci + im[i + k + len / 2] * cr;
        re[i + k] = ur + vr; im[i + k] = ui + vi;
        re[i + k + len / 2] = ur - vr; im[i + k + len / 2] = ui - vi;
        const nr = cr * wr - ci * wi;
        ci = cr * wi + ci * wr;
        cr = nr;
      }
    }
  }
  if (inverse) for (let i = 0; i < n; i++) { re[i] /= n; im[i] /= n; }
}

const ramp = (f, lo, hi) => (f <= lo ? 0 : f >= hi ? 1 : 0.5 - 0.5 * Math.cos(Math.PI * (f - lo) / (hi - lo)));

// Keeps only the given frequency band of x, without shifting it in time (zero phase).
function bandLimit(x, band) {
  return spectralShape(x, (f) => ramp(f, band[0], band[1]) * (1 - ramp(f, band[2], band[3])));
}

// Multiplies the spectrum of x by gain(frequency in Hz), without shifting it in time.
function spectralShape(x, gain) {
  let size = 1;
  while (size < x.length * 2) size <<= 1;
  const re = new Float64Array(size);
  const im = new Float64Array(size);
  re.set(x);
  fft(re, im, false);
  for (let k = 0; k <= size / 2; k++) {
    const f = k * IR_RATE / size;
    const g = gain(f);
    re[k] *= g; im[k] *= g;
    if (k > 0 && k < size / 2) { re[size - k] *= g; im[size - k] *= g; }
  }
  fft(re, im, true);
  return re.subarray(0, x.length);
}

// Colouring that makes a sound seem to come from above: energy around 7-8 kHz is the band the ear
// associates with "overhead", and the outer-ear notch that sits near 6-8 kHz at ear level moves up
// towards 11 kHz as a source rises. Overhead speakers also carry no bass.
function heightCurve(f) {
  const bell = (fc, q) => 1 / (1 + Math.pow((f / fc - fc / f) * q, 2));
  const db = f > 0 ? 7 * bell(7500, 2.5) - 8 * bell(11000, 4) : 0;
  return ramp(f, 120, 260) * Math.pow(10, db / 20);
}
const HEIGHT_PAD = Math.round(IR_RATE * 0.016);

// Measured elevation cue from the MIT KEMAR dummy head (hrtf-kemar/, sound.media.mit.edu).
// The raw measurements also contain the ear canal and the measuring loudspeaker, which must not be
// applied a second time on top of the HRIR set in use. Dividing "50 degrees up" by "ear level" at the
// same side angle cancels those and leaves only what raising the source changes, per ear.
const KEMAR_DIR = path.join(__dirname, 'hrtf-kemar');
let kemarCue = null;

function kemarPower(name) {
  const wav = readWavChannels(path.join(KEMAR_DIR, name));
  const size = 1024;
  const re = new Float64Array(size);
  const im = new Float64Array(size);
  re.set(wav.channels[0].subarray(0, size));
  fft(re, im, false);
  const p = new Float64Array(size / 2 + 1);
  for (let k = 0; k <= size / 2; k++) p[k] = re[k] * re[k] + im[k] * im[k];
  return { p, binHz: wav.rate / size };
}

// Third-octave smoothed level ratio, limited to +/-6 dB (the full measured +12 dB around 7-9 kHz
// was heard as a piercing tone).
function kemarRatio(topName, levelName) {
  const top = kemarPower(topName);
  const level = kemarPower(levelName);
  return (f) => {
    const lo = Math.max(1, Math.floor(f / 1.12 / top.binHz));
    const hi = Math.min(top.p.length - 1, Math.max(lo, Math.ceil(f * 1.12 / top.binHz)));
    let a = 0;
    let b = 0;
    for (let k = lo; k <= hi; k++) { a += top.p[k]; b += level.p[k]; }
    return Math.max(0.5, Math.min(2, Math.sqrt(a / Math.max(b, 1e-20))));
  };
}

function loadKemarCue() {
  if (!kemarCue) {
    kemarCue = {
      // ear on the same side as the overhead speaker, and the ear on the far side
      near: kemarRatio('elev50/L50e328a.wav', 'elev0/L0e330a.wav'),
      far: kemarRatio('elev50/L50e032a.wav', 'elev0/L0e030a.wav'),
    };
  }
  return kemarCue;
}

// One response per input channel and ear: the sum, over the virtual speakers, of how much of that
// input each speaker gets times how that speaker sounds at that ear.
function buildStyleIr(style) {
  const wav = readWavChannels(path.join(APO_DIR, 'config', 'HeSuVi', 'hrir', style.hrir));
  if (wav.rate !== IR_RATE || wav.channels.length < 14) throw new Error('HRIR file has an unexpected format');
  const mix = style.mix || UPMIX[style.upmix];
  const hn = wav.channels[0].length;
  // Silent lead-in so that filters which ring before the sound have somewhere to put it.
  const PRE = 1024;
  const n = PRE + hn + (style.height ? HEIGHT_PAD : 0);
  const res = [[new Float64Array(n), new Float64Array(n)], [new Float64Array(n), new Float64Array(n)]];
  for (const spk of Object.keys(mix)) {
    for (let input = 0; input < 2; input++) {
      const g = mix[spk][input];
      if (!g) continue;
      for (let ear = 0; ear < 2; ear++) {
        const h = wav.channels[HRIR_CH[spk][ear]];
        const dst = res[input][ear];
        for (let i = 0; i < hn; i++) dst[PRE + i] += g * h[i];
      }
    }
  }
  if (style.height) {
    // Two overhead speakers, front-left-up and front-right-up. Each is built from the front and
    // side responses of its own side, coloured with heightCurve, and arrives a few milliseconds
    // late like a reflection off a ceiling. They are fed almost only with what differs between
    // the two inputs (ambience, width), so lead vocals stay where they are.
    for (let side = 0; side < 2; side++) {
      const front = side === 0 ? 'FL' : 'FR';
      const surround = side === 0 ? 'SL' : 'SR';
      const delay = Math.min(HEIGHT_PAD, Math.round(IR_RATE * style.height.delayMs[side] / 1000));
      for (let ear = 0; ear < 2; ear++) {
        const f = wav.channels[HRIR_CH[front][ear]];
        const sv = wav.channels[HRIR_CH[surround][ear]];
        const base = new Float64Array(PRE + hn);
        for (let i = 0; i < hn; i++) base[PRE + i] = 0.6 * f[i] + 0.4 * sv[i];
        let curve = heightCurve;
        if (style.height.measured) {
          const cue = ear === side ? loadKemarCue().near : loadKemarCue().far;
          curve = (fq) => ramp(fq, 120, 260) * cue(Math.min(Math.max(fq, 100), 18000));
        }
        const shaped = spectralShape(base, curve);
        for (let input = 0; input < 2; input++) {
          const g = style.height.gain * (input === side ? 0.45 : -0.35);
          const dst = res[input][ear];
          for (let i = 0; i < PRE + hn; i++) dst[i + delay] += g * shaped[i];
        }
      }
    }
  }
  if (style.sideGain) {
    for (let ear = 0; ear < 2; ear++) {
      const a = res[0][ear];
      const b = res[1][ear];
      for (let i = 0; i < n; i++) {
        const mid = a[i] + b[i];
        const side = (a[i] - b[i]) * style.sideGain;
        a[i] = (mid + side) / 2;
        b[i] = (mid - side) / 2;
      }
    }
  }
  if (style.vocalTail) {
    // Split each ear's responses into "middle" (what both inputs share: lead vocals, bass, kick)
    // and "side" (what differs: width and ambience). Only the middle part's reverb tail is
    // turned down; its first arrival and the whole side part are left alone.
    const hold = Math.round(IR_RATE * 0.004);
    const fade = Math.round(IR_RATE * 0.006);
    for (let ear = 0; ear < 2; ear++) {
      const a = res[0][ear];
      const b = res[1][ear];
      let p = 0;
      let pk = 0;
      for (let i = 0; i < n; i++) { const v = Math.abs(a[i] + b[i]); if (v > pk) { pk = v; p = i; } }
      // What would be removed from the middle signal: nothing during the first arrival, then
      // (1 - vocalTail) of the tail. Only the vocal range of that is actually taken away.
      const cut = new Float64Array(n);
      for (let i = 0; i < n; i++) {
        const t = i - (p + hold);
        const w = t <= 0 ? 1 : (t >= fade ? style.vocalTail : 1 - (1 - style.vocalTail) * (t / fade));
        cut[i] = (a[i] + b[i]) * (1 - w);
      }
      const removed = bandLimit(cut, VOCAL_BAND);
      for (let i = 0; i < n; i++) {
        const mid = a[i] + b[i] - removed[i];
        const side = a[i] - b[i];
        a[i] = (mid + side) / 2;
        b[i] = (mid - side) / 2;
      }
    }
  }
  if (style.tone) {
    // Measured: for ordinary stereo the set is tonally flat (within about 1 dB), but for sound that is
    // the same in both inputs - vocals, kick, bass - the two front speakers add up in the bass and partly
    // cancel higher up, giving +3 dB below 250 Hz and -2 dB above 500 Hz. That is what sounds muffled.
    // So the correction is worked out for, and applied to, that middle signal only; the side signal
    // (width, ambience) is left as it is.
    const size = 16384;
    const power = new Float64Array(size / 2 + 1);
    for (let ear = 0; ear < 2; ear++) {
      const re = new Float64Array(size);
      const im = new Float64Array(size);
      for (let i = 0; i < Math.min(n, size); i++) re[i] = res[0][ear][i] + res[1][ear][i];
      fft(re, im, false);
      for (let k = 0; k <= size / 2; k++) power[k] += re[k] * re[k] + im[k] * im[k];
    }
    const binHz = IR_RATE / size;
    const smooth = (f) => {
      const lo = Math.max(1, Math.floor(f / 1.19 / binHz));
      const hi = Math.min(size / 2, Math.max(lo, Math.ceil(f * 1.19 / binHz)));
      let sum = 0;
      for (let k = lo; k <= hi; k++) sum += power[k];
      return sum / (hi - lo + 1);
    };
    // Reference level: the average over the range that carries most of the music.
    let ref = 0;
    let count = 0;
    for (let f = 200; f <= 8000; f *= 1.06) { ref += Math.log(smooth(f)); count++; }
    ref = Math.exp(ref / count);
    const correction = (f) => {
      const fq = Math.min(Math.max(f, 30), 16000);
      const db = Math.max(-6, Math.min(6, style.tone * 10 * Math.log10(ref / smooth(fq))));
      return Math.pow(10, db / 20);
    };
    for (let ear = 0; ear < 2; ear++) {
      const a = res[0][ear];
      const b = res[1][ear];
      const mid = new Float64Array(n);
      for (let i = 0; i < n; i++) mid[i] = a[i] + b[i];
      const fixed = spectralShape(mid, correction);
      for (let i = 0; i < n; i++) {
        const side = a[i] - b[i];
        a[i] = (fixed[i] + side) / 2;
        b[i] = (fixed[i] - side) / 2;
      }
    }
  }
  if (style.vocalDb) {
    // Add (or take away) a share of the middle signal's vocal range. Bass and kick, also in the
    // middle but below that range, and everything at the sides keep their level.
    const extra = Math.pow(10, style.vocalDb / 20) - 1;
    for (let ear = 0; ear < 2; ear++) {
      const a = res[0][ear];
      const b = res[1][ear];
      const mid = new Float64Array(n);
      for (let i = 0; i < n; i++) mid[i] = a[i] + b[i];
      const voice = bandLimit(mid, VOCAL_BAND);
      for (let i = 0; i < n; i++) {
        const m2 = mid[i] + extra * voice[i];
        const side = a[i] - b[i];
        a[i] = (m2 + side) / 2;
        b[i] = (m2 - side) / 2;
      }
    }
  }
  if (style.distance) {
    // After the tone correction, which would otherwise undo it. Far away (band headphones): the direct sound duller (a blend towards a 3.5 kHz one-pole
    // low-pass, up to 75 %), and diffuse low-passed sound from the side and rear speakers.
    const d = style.distance;
    const dark = (fq) => { const r = fq / 3500, q = 1 + r * r; return Math.hypot(1 - 0.75 * d + 0.75 * d / q, 0.75 * d * r / q); };
    for (const pair of res) for (let ear = 0; ear < 2; ear++) {
      const shaped = spectralShape(pair[ear], dark);
      for (let i = 0; i < n; i++) pair[ear][i] = shaped[i];
    }
    const g = 0.22 * d / (1 + 2.2 * d);
    const around = { SL: [g, 0], SR: [0, g], RL: [g, 0], RR: [0, g] };
    const lp = (fq) => 1 / Math.sqrt(1 + (fq / 3500) * (fq / 3500));
    for (const spk of Object.keys(around)) {
      for (let input = 0; input < 2; input++) {
        const gi = around[spk][input];
        if (!gi) continue;
        for (let ear = 0; ear < 2; ear++) {
          const h = new Float64Array(n);
          const src = wav.channels[HRIR_CH[spk][ear]];
          for (let i = 0; i < hn; i++) h[PRE + i] = gi * src[i];
          const shaped = spectralShape(h, lp);
          // both inputs feed the diffuse sound, as the demo's mono sum does
          for (let i = 0; i < n; i++) { res[0][ear][i] += shaped[i] / 2; res[1][ear][i] += shaped[i] / 2; }
        }
      }
    }
  }
  if (style.lowShelfDb) {
    // A first-order low shelf at 150 Hz on the whole response (band headphones: drums and bass).
    const G = Math.pow(10, style.lowShelfDb / 20);
    const shelf = (fq) => { const r = (fq / 150) * (fq / 150); return Math.sqrt((G * G + r) / (1 + r)); };
    for (const pair of res) for (let ear = 0; ear < 2; ear++) {
      const shaped = spectralShape(pair[ear], shelf);
      for (let i = 0; i < n; i++) pair[ear][i] = shaped[i];
    }
  }
  let peak = 1e-9;
  let last = 0;
  let first = n;
  for (const pair of res) for (const ch of pair) for (let i = 0; i < n; i++) { const a = Math.abs(ch[i]); if (a > peak) peak = a; if (a > 1e-5) { last = Math.max(last, i); if (i < first) first = i; } }
  // Drop the part of the lead-in nothing used (the same amount from all four, so they stay aligned).
  // (keepLeadIn: all of it stays, so that several responses meant to be added stay aligned.)
  const start = style.keepLeadIn ? 0 : Math.max(0, Math.min(first, PRE) - 32);
  // The page sets the playback level itself, so the files are simply scaled to use the full 16 bits
  // (or by a given factor, when several responses must keep their levels relative to each other).
  const scale = style.scale || 0.9 / peak;
  const frames = Math.min(n, last + 257) - start;
  const toWav = (pair) => pcm16Wav(2, frames, (d) => {
    for (let i = 0; i < frames; i++) {
      d.writeInt16LE(Math.round(Math.max(-1, Math.min(1, pair[0][start + i] * scale)) * 32767), i * 4);
      d.writeInt16LE(Math.round(Math.max(-1, Math.min(1, pair[1][start + i] * scale)) * 32767), i * 4 + 2);
    }
  });
  return { L: toWav(res[0]), R: toWav(res[1]), scale };
}

// Base sets offered to the slider-based style editor.
const BASES = [
  { id: 'dh', name: 'Dolby Headphone', hrir: 'dh+.wav' },
  { id: 'dh-large', name: 'Dolby Headphone（另一種空間）', hrir: 'dh++.wav' },
  { id: 'dht', name: 'Dolby Home Theater', hrir: 'dht.wav' },
  { id: 'atmos', name: 'Dolby Atmos Headphone', hrir: 'atmos.wav' },
  { id: 'dtshx', name: 'DTS Headphone:X', hrir: 'dtshx.wav' },
  { id: 'gsx', name: 'Sennheiser GSX', hrir: 'gsx++.wav' },
  { id: 'sbx', name: 'Creative SBX', hrir: 'sbx67.wav' },
  { id: 'waves', name: 'Waves Nx', hrir: 'waves.wav' },
];

function availableBases() {
  const list = [{ id: 'hesuvi', name: '目前的 HeSuVi 設定（滑桿不適用）' }];
  for (const b of BASES) if (fs.existsSync(path.join(APO_DIR, 'config', 'HeSuVi', 'hrir', b.hrir))) list.push({ id: b.id, name: b.name });
  return list;
}

// Slider values arrive as whole percentages: width 0-100, vocal 0-80, height 0-150, tone 0-100.
const customIrCache = new Map();

function getCustomIr(q) {
  const base = BASES.find((b) => b.id === q.get('b'));
  if (!base) return q.get('b') === 'hesuvi' ? getIr() : Promise.reject(new Error('unknown base'));
  const pct = (name, max) => Math.max(0, Math.min(max, Math.round(Number(q.get(name)) || 0)));
  const w = pct('w', 100);
  const v = pct('v', 80);
  const h = pct('h', 150);
  const t = pct('t', 180);
  const o = pct('o', 100);
  // vocal level in tenths of a decibel, -60..60
  const g = Math.max(-60, Math.min(60, Math.round(Number(q.get('g')) || 0)));
  const key = [base.id, w, v, h, t, o, g].join('|');
  if (!customIrCache.has(key)) {
    const mix = {};
    for (const spk of Object.keys(UPMIX.standard)) {
      mix[spk] = [0, 1].map((i) => UPMIX.standard[spk][i] + (UPMIX.wide[spk][i] - UPMIX.standard[spk][i]) * w / 100);
    }
    // Openness: part of what each front speaker plays is moved to the side speaker on the same
    // side, as if the front pair stood further apart, and the width (side) signal is turned up.
    if (o > 0) {
      const a = 0.5 * o / 100;
      mix.SL = [mix.SL[0] + mix.FL[0] * a, mix.SL[1]];
      mix.SR = [mix.SR[0], mix.SR[1] + mix.FR[1] * a];
      mix.FL = [mix.FL[0] * (1 - a), mix.FL[1]];
      mix.FR = [mix.FR[0], mix.FR[1] * (1 - a)];
    }
    const style = { hrir: base.hrir, mix };
    if (o > 0) style.sideGain = 1 + 0.4 * o / 100;
    if (g !== 0) style.vocalDb = g / 10;
    if (v > 0) style.vocalTail = 1 - v / 100;
    if (h > 0) style.height = { gain: h / 100, delayMs: [8, 10] };
    // 100% keeps the strength this correction had when it was tuned by ear (an earlier filter bug made
    // it weaker than intended); the slider goes on to 180% for the full correction.
    if (t > 0) style.tone = 0.56 * t / 100;
    customIrCache.set(key, buildStyleIr(style));
    while (customIrCache.size > 40) customIrCache.delete(customIrCache.keys().next().value);
  }
  return Promise.resolve(customIrCache.get(key));
}

// ---------------------------------------------------------------- surround rendered on this PC

const FX_VERSION = 2;
// Sum of squares of each channel of a WAV file held in memory.
function wavEnergy(buf) {
  let off = 12, fmt = null, data = null;
  while (off + 8 <= buf.length) {
    const name = buf.toString('ascii', off, off + 4), size = buf.readUInt32LE(off + 4);
    if (name === 'fmt ') fmt = { tag: buf.readUInt16LE(off + 8), ch: buf.readUInt16LE(off + 10), bits: buf.readUInt16LE(off + 22) };
    if (name === 'data') { data = buf.subarray(off + 8, Math.min(buf.length, off + 8 + size)); break; }
    off += 8 + size + (size & 1);
  }
  if (!fmt || !data) throw new Error('impulse response is not a WAV file');
  const bytes = fmt.bits / 8, frames = Math.floor(data.length / (bytes * fmt.ch));
  const e = new Array(fmt.ch).fill(0);
  for (let i = 0; i < frames; i++) {
    for (let c = 0; c < fmt.ch; c++) {
      const at = (i * fmt.ch + c) * bytes;
      let v;
      if (fmt.bits === 16) v = data.readInt16LE(at) / 32768;
      else if (fmt.bits === 24) v = data.readIntLE(at, 3) / 8388608;
      else if (fmt.bits === 32 && fmt.tag === 3) v = data.readFloatLE(at);
      else if (fmt.bits === 32) v = data.readInt32LE(at) / 2147483648;
      else throw new Error('unsupported WAV sample size');
      e[c] += v * v;
    }
  }
  return e;
}

// A song fetched whole from this server's own stream relay into a file (a plain request: fast).
function fetchSong(id, file) {
  return new Promise((resolve, reject) => {
    const req = http.get({ host: '127.0.0.1', port: PORT, path: '/media/' + id + '.m4a?mode=phone' }, (r) => {
      if (r.statusCode !== 200) { r.resume(); return reject(new Error('source HTTP ' + r.statusCode)); }
      const out = fs.createWriteStream(file);
      r.pipe(out);
      out.on('finish', resolve);
      out.on('error', reject);
      r.on('error', reject);
    });
    req.on('error', reject);
    req.setTimeout(60000, () => req.destroy(new Error('source timed out')));
  });
}
function fileLufs(file, cwd) {
  return new Promise((resolve) => {
    const p = spawn('ffmpeg', ['-hide_banner', '-nostats', '-i', file, '-vn', '-af', 'ebur128=framelog=quiet', '-f', 'null', '-'], { cwd, env: TOOL_ENV, windowsHide: true, stdio: ['ignore', 'ignore', 'pipe'] });
    let err = '';
    p.stderr.on('data', (c) => { err += c; if (err.length > 20000) err = err.slice(-10000); });
    p.on('error', () => resolve(NaN));
    p.on('close', () => {
      const all = err.match(/I:\s+(-?[\d.]+) LUFS/g);
      const m = all && /(-?[\d.]+) LUFS/.exec(all[all.length - 1]);
      resolve(m ? Number(m[1]) : NaN);
    });
  });
}
// How strong the bass and the middle of a song are, thirty times a second, as two bytes per step.
// The page moves its backdrop light by this when it cannot listen to the sound itself.
function ensureEnv(id) {
  const file = path.join(CACHE_ROOT, 'env', id + '.bin');
  return ensure(file, async () => {
    const work = workDir(id + '-env');
    try {
      await fetchSong(id, path.join(work, 'src.m4a'));
      await run('ffmpeg', ['-y', '-loglevel', 'error', '-i', 'src.m4a', '-vn', '-ac', '1', '-ar', '11025', '-f', 's16le', 'pcm.raw'], work);
      const b = fs.readFileSync(path.join(work, 'pcm.raw'));
      const x = new Int16Array(b.buffer, b.byteOffset, Math.floor(b.length / 2));
      const sr = 11025, rate = 30, n = Math.floor(x.length * rate / sr);
      const out = Buffer.alloc(n * 2);
      const aLow = Math.exp(-2 * Math.PI * 180 / sr), aLo = Math.exp(-2 * Math.PI * 400 / sr), aHi = Math.exp(-2 * Math.PI * 2800 / sr);
      let low = 0, lo = 0, hi = 0;
      for (let f = 0; f < n; f++) {
        const from = Math.floor(f * sr / rate), to = Math.floor((f + 1) * sr / rate);
        let eb = 0, em = 0;
        for (let i = from; i < to; i++) {
          const v = x[i] / 32768;
          low = low * aLow + v * (1 - aLow);
          lo = lo * aLo + v * (1 - aLo);
          hi = hi * aHi + v * (1 - aHi);
          const mid = hi - lo;
          eb += low * low;
          em += mid * mid;
        }
        const k = Math.max(1, to - from);
        // square root twice: the byte keeps detail in quiet passages
        out[f * 2] = Math.min(255, Math.round(255 * Math.sqrt(Math.sqrt(eb / k))));
        out[f * 2 + 1] = Math.min(255, Math.round(255 * Math.sqrt(Math.sqrt(em / k))));
      }
      fs.mkdirSync(path.dirname(file), { recursive: true });
      fs.writeFileSync(file, out);
    } finally { cleanup(work); }
  }).then(() => file);
}
// The finished file for one song with one set of sound settings; made once, then kept.
async function ensureFx(id, q) {
  const on = q.get('s') !== '0';
  const eq = String(q.get('eq') || '').split(',').slice(0, 5).map((x) => Math.max(-12, Math.min(12, Math.round((Number(x) || 0) * 10) / 10)));
  while (eq.length < 5) eq.push(0);
  const nRaw = q.get('n');
  const target = nRaw === null || nRaw === '' || !Number.isFinite(Number(nRaw)) ? null : Math.max(-16, Math.min(-5, Number(nRaw)));
  let custom = null;
  let irKey = 'off';
  if (on) {
    custom = await getCustomIr(q);
    irKey = ['b', 'w', 'v', 'h', 't', 'o', 'g'].map((k) => String(Number(q.get(k)) || q.get(k) || 0)).join('|');
  }
  // The loudness is baked into the file, so it has to be known first.
  let work = null, file = null;
  const source = async () => {
    if (!work) { work = workDir(id + '-fx'); await fetchSong(id, path.join(work, 'src.m4a')); }
    return work;
  };
  try {
  if (target !== null && !loudness.has(id)) {
    await source();
    const v = await fileLufs('src.m4a', work);
    if (Number.isFinite(v) && v > -60 && v < 5) { loudness.set(id, v); saveLoudnessSoon(); }
  }
  const lufs = loudness.get(id);
  const normDb = target === null ? 0 : (typeof lufs === 'number' ? Math.max(-12, Math.min(6, target - lufs)) : -4);
  const key = crypto.createHash('sha1').update(JSON.stringify([FX_VERSION, irKey, eq, Math.round(normDb * 10)])).digest('hex').slice(0, 12);
  file = path.join(CACHE_ROOT, 'fx', key, id + '.m4a');
  await ensure(file, async () => {
    await source();
    {
      const inputs = ['-i', 'src.m4a'];
      let makeup = 0.708;
      let chain = '[0:a]aresample=48000,aformat=sample_fmts=fltp:channel_layouts=stereo';
      if (custom) {
        fs.writeFileSync(path.join(work, 'L.wav'), custom.L);
        fs.writeFileSync(path.join(work, 'R.wav'), custom.R);
        const eL = wavEnergy(custom.L), eR = wavEnergy(custom.R);
        const e = (eL[0] + eL[1] + eR[0] + eR[1]) / 2;
        if (e > 0) makeup *= Math.min(8, Math.max(0.25, 1 / Math.sqrt(e)));
        inputs.push('-i', 'L.wav', '-i', 'R.wav');
        // Left and right channel each go through their own two-channel impulse response; the sum is the result.
        const fir = 'afir=dry=1:wet=1:irnorm=-1:irlink=0:irgain=1';
        chain += ',asplit=2[a][b];[a]pan=stereo|c0=c0|c1=c0[l];[b]pan=stereo|c0=c1|c1=c1[r];[l][1:a]' + fir + '[ol];[r][2:a]' + fir + '[or];[ol][or]amix=inputs=2:normalize=0';
      }
      const post = ['volume=' + (makeup * Math.pow(10, normDb / 20)).toFixed(5)];
      if (eq[0]) post.push('lowshelf=f=150:t=s:w=1:g=' + eq[0]);
      if (eq[1]) post.push('equalizer=f=400:t=q:w=1:g=' + eq[1]);
      if (eq[2]) post.push('equalizer=f=1500:t=q:w=1:g=' + eq[2]);
      if (eq[3]) post.push('equalizer=f=5000:t=q:w=1:g=' + eq[3]);
      if (eq[4]) post.push('highshelf=f=10000:t=s:w=1:g=' + eq[4]);
      post.push('alimiter=limit=0.891:attack=2:release=120:level=false');
      chain += ',' + post.join(',') + '[out]';
      await run('ffmpeg', ['-y', '-loglevel', 'error'].concat(inputs, ['-filter_complex', chain, '-map', '[out]', '-c:a', 'aac', '-b:a', '256k', '-ar', '44100', '-movflags', '+faststart', 'out.m4a']), work);
      fs.mkdirSync(path.dirname(file), { recursive: true });
      fs.renameSync(path.join(work, 'out.m4a'), file);
    }
  });
  } finally { if (work) cleanup(work); }
  return file;
}

const styleIrCache = new Map();

// "Band" surround for headphones (test build): the app separates a song into four parts and
// sends each through its own virtual speakers: [from left input, from right input] per speaker.
const BAND_MIX = {
  drums: { C: [0.2, 0.2], FL: [0.4, 0], FR: [0, 0.4] },
  bass: { C: [0.5, 0.5] },
  other: { FL: [0.4, 0], FR: [0, 0.4], SL: [0.35, -0.15], SR: [-0.15, 0.35] },
  vocals: { C: [0.5, 0.5] },
};

// A part at a position: its left input at azimuth - 30 x width, its right input at
// azimuth + 30 x width (all the way round: -180 .. 180, 0 = ahead), each panned (constant power)
// between the two nearest of the seven virtual speakers. Distance d (0 .. 1) as in the PC demo:
// the direct sound is divided by 1 + 2.2 d and made duller (buildStyleIr, style.distance), and
// some diffuse sound comes from the sides and back.
const BAND_SPEAKERS = [['RL', -150], ['SL', -90], ['FL', -30], ['C', 0], ['FR', 30], ['SR', 90], ['RR', 150], ['RL', 210]];
function bandPositionMix(az, widthPct, depthPct) {
  const mix = {};
  const add = (spk, input, g) => { if (!mix[spk]) mix[spk] = [0, 0]; mix[spk][input] += g; };
  const w = Math.max(0, Math.min(2, widthPct / 100));
  const d = Math.max(0, Math.min(1, depthPct / 100));
  [az - 30 * w, az + 30 * w].forEach((angle, input) => {
    let x = ((angle % 360) + 360) % 360;      // 0 .. 360
    if (x > 180) x -= 360;                    // -180 .. 180
    if (x < -150) x += 360;                   // between RR (150) and RL (210)
    let i = 0;
    while (i < BAND_SPEAKERS.length - 2 && x > BAND_SPEAKERS[i + 1][1]) i++;
    const [s0, a0] = BAND_SPEAKERS[i], [s1, a1] = BAND_SPEAKERS[i + 1];
    const t = Math.max(0, Math.min(1, (x - a0) / (a1 - a0)));
    const g = 0.5 / (1 + 2.2 * d);
    add(s0, input, g * Math.cos(t * Math.PI / 2));
    add(s1, input, g * Math.sin(t * Math.PI / 2));
  });
  return mix;
}
const bandPosCache = new Map();

// One part's responses: at its position (az, w, d; without them the fixed default mix), with
// the user's tone correction (t, as the headphone style uses it), the vocal tail (v, vocals
// only) and a low shelf (lo, tenths of a dB, drums and bass only). One fixed scale per base
// (that of its plain stereo spread), so levels do not move with position or between parts.
function getBandIr(name, q) {
  const wanted = q.get('b') || 'dh';
  const have = (b) => fs.existsSync(path.join(APO_DIR, 'config', 'HeSuVi', 'hrir', b.hrir));
  const base = BASES.find((b) => b.id === wanted && have(b)) || BASES.find(have);
  if (!base) return Promise.reject(new Error('no HRIR base available'));
  const num = (k, lo, hi, def) => { const v = q.get(k); const x = Math.round(Number(v)); return v === null || !isFinite(x) ? def : Math.max(lo, Math.min(hi, x)); };
  const positioned = q.get('az') !== null;
  const az = num('az', -180, 180, 0), w = num('w', 0, 200, 0), d = num('d', 0, 100, 0);
  const t = num('t', 0, 180, 0);
  const v = name === 'vocals' ? num('v', 0, 80, 0) : 0;
  const lo = name === 'drums' || name === 'bass' ? num('lo', -60, 30, 0) : 0;
  const key = [name, base.id, positioned ? [az, w, d].join(',') : 'default', t, v, lo].join('|');
  if (!bandPosCache.has(key)) {
    const sk = 'scale|' + base.id;
    if (!bandPosCache.has(sk)) bandPosCache.set(sk, buildStyleIr({ hrir: base.hrir, mix: UPMIX.standard, keepLeadIn: true }).scale);
    const style = { hrir: base.hrir, mix: positioned ? bandPositionMix(az, w, d) : BAND_MIX[name], keepLeadIn: true, scale: bandPosCache.get(sk) };
    if (t > 0) style.tone = 0.56 * t / 100;
    if (v > 0) style.vocalTail = 1 - v / 100;
    if (lo !== 0) style.lowShelfDb = lo / 10;
    if (positioned && d > 0) style.distance = d / 100;
    bandPosCache.set(key, buildStyleIr(style));
    while (bandPosCache.size > 120) bandPosCache.delete(bandPosCache.keys().next().value);
  }
  return Promise.resolve(bandPosCache.get(key));
}

function getStyleIr(id) {
  if (id === 'hesuvi') return getIr();
  const style = STYLES.find((x) => x.id === id);
  if (!style) return Promise.reject(new Error('unknown style'));
  if (!styleIrCache.has(id)) styleIrCache.set(id, buildStyleIr(style));
  return Promise.resolve(styleIrCache.get(id));
}

function availableStyles() {
  const haveKemar = fs.existsSync(path.join(KEMAR_DIR, 'elev50', 'L50e328a.wav'));
  return STYLES.filter((x) => (!x.hrir || fs.existsSync(path.join(APO_DIR, 'config', 'HeSuVi', 'hrir', x.hrir))) && (!(x.height && x.height.measured) || haveKemar))
    .map((x) => ({ id: x.id, name: x.name }));
}

// ---------------------------------------------------------------- home-screen app identity

// A manifest with its own id and an icon, so the phone treats this player as a separate app from
// other pages served by the same PC.
const zlib = require('zlib');

function makeIcon(size) {
  const raw = Buffer.alloc((size * 4 + 1) * size);
  const c = size / 2;
  const r = size * 0.36;
  for (let y = 0; y < size; y++) {
    const row = y * (size * 4 + 1);
    for (let x = 0; x < size; x++) {
      const dx = x - c;
      const dy = y - c;
      let px = [15, 15, 20];
      if (dx * dx + dy * dy <= r * r) {
        px = [124, 92, 255];
        // Play triangle: apex on the right, base on the left.
        const tx = dx + r * 0.3;
        if (tx >= 0 && tx <= r * 0.8 && Math.abs(dy) <= (r * 0.8 - tx) * 0.62) px = [255, 255, 255];
      }
      const o = row + 1 + x * 4;
      raw[o] = px[0]; raw[o + 1] = px[1]; raw[o + 2] = px[2]; raw[o + 3] = 255;
    }
  }
  const chunk = (type, data) => {
    const body = Buffer.concat([Buffer.from(type, 'ascii'), data]);
    const out = Buffer.alloc(body.length + 8);
    out.writeUInt32BE(data.length, 0);
    body.copy(out, 4);
    out.writeUInt32BE(zlib.crc32(body) >>> 0, body.length + 4);
    return out;
  };
  const head = Buffer.alloc(13);
  head.writeUInt32BE(size, 0); head.writeUInt32BE(size, 4);
  head[8] = 8; head[9] = 6;
  return Buffer.concat([Buffer.from([137, 80, 78, 71, 13, 10, 26, 10]), chunk('IHDR', head), chunk('IDAT', zlib.deflateSync(raw)), chunk('IEND', Buffer.alloc(0))]);
}

const ICONS = { 180: makeIcon(180), 512: makeIcon(512) };
const MANIFEST = JSON.stringify({
  id: '/harmonia', name: 'Harmonia', short_name: 'Harmonia', start_url: '/', scope: '/',
  display: 'standalone', background_color: '#030303', theme_color: '#030303',
  icons: [{ src: '/icon-180.png', sizes: '180x180', type: 'image/png' }, { src: '/icon-512.png', sizes: '512x512', type: 'image/png' }],
});

// ---------------------------------------------------------------- routes

async function handle(req, res) {
  const url = new URL(req.url, 'http://x');
  const p = url.pathname;
  const GET = req.method === 'GET';
  const POST = req.method === 'POST';
  const mode = url.searchParams.get('mode') === 'server' ? 'server' : 'phone';
  if (!p.startsWith('/agent/')) {
    // A request started by some other web page carries that page's address in Origin or Referer.
    // Refuse those, so no outside page can like songs, edit playlists or start work on this PC.
    const from = req.headers.origin || req.headers.referer || '';
    if (from) {
      let host = '';
      try { host = new URL(from).host; } catch (e) { host = 'invalid'; }
      if (host !== (req.headers.host || '')) return send(res, 403, { error: 'cross-site request refused' });
    }
    // Writes must be JSON: a plain cross-site form or no-cors fetch cannot send that content type.
    if (POST && !/^application\/json\b/i.test(req.headers['content-type'] || '')) return send(res, 415, { error: 'JSON required' });
  }
  if (p.startsWith('/api/') && p !== '/api/agent') playerUsedAt = Date.now();

  if (GET && (p === '/' || p === '/index.html')) {
    return send(res, 200, fs.readFileSync(path.join(__dirname, 'index.html')), 'text/html; charset=utf-8');
  }
  if (GET && p === '/manifest.webmanifest') return send(res, 200, MANIFEST, 'application/manifest+json');
  const icon = /^\/icon-(180|512)\.png$/.exec(p);
  if (GET && icon) return send(res, 200, ICONS[icon[1]], 'image/png');
  if (GET && p === '/ytm-remote.user.js') {
    return send(res, 200, fs.readFileSync(path.join(__dirname, 'ytm-remote.user.js')), 'text/javascript; charset=utf-8');
  }

  let m = /^\/media\/([\w-]{11})\.m4a$/.exec(p);
  if (m && req.method === 'HEAD' && mode === 'phone' && url.searchParams.get('fx') !== '1') {
    try { await resolveUrl(m[1]); } catch (e) { res.writeHead(502); return res.end(); }
    res.writeHead(200, { 'Content-Type': 'audio/mp4', 'Accept-Ranges': 'bytes', 'Content-Length': (streamUrls.get(m[1]) || {}).size || 0 });
    return res.end();
  }
  if (m && (GET || req.method === 'HEAD') && mode === 'phone' && url.searchParams.get('fx') === '1') {
    let made;
    const t0 = Date.now();
    try { made = await ensureFx(m[1], url.searchParams); } catch (e) { console.error('fx ' + m[1] + ': ' + (e.message || e)); return send(res, 502, { error: String(e.message || e) }); }
    if (Date.now() - t0 > 300) console.log(new Date().toTimeString().slice(0, 8) + ' fx ' + m[1] + ' made in ' + (Date.now() - t0) + ' ms');
    return serveFile(req, res, made, 'audio/mp4');
  }
  if (m && GET && mode === 'phone') return proxyMedia(req, res, m[1], false);
  if (m && (GET || req.method === 'HEAD')) return serveFile(req, res, mediaPath(m[1], mode), 'audio/mp4');

  m = /^\/api\/track\/([^/]+)\/(status|prepare)$/.exec(p);
  if (m) {
    if (!ID_RE.test(m[1])) return send(res, 400, { error: 'bad videoId' });
    if (GET && m[2] === 'status') return send(res, 200, trackStatus(m[1], mode));
    if (POST && m[2] === 'prepare') return send(res, 200, prepare(m[1], mode));
  }
  if (POST && p === '/api/warm') {
    const b = await readBody(req);
    if (!b || !Array.isArray(b.ids)) return send(res, 400, { error: 'bad ids' });
    warm(b.ids.slice(0, 12).filter((id) => ID_RE.test(id)));
    return send(res, 200, { ok: true });
  }
  if (POST && p === '/api/prefetch') {
    const b = await readBody(req);
    if (!b || !Array.isArray(b.ids)) return send(res, 400, { error: 'bad ids' });
    const pm = b.mode === 'server' ? 'server' : 'phone';
    for (const id of b.ids.slice(0, 5)) if (ID_RE.test(id)) prepare(id, pm);
    return send(res, 200, { ok: true });
  }

  try {
    m = /^\/api\/song\/([\w-]{11})\/(like|playlists|save|comments)$/.exec(p);
    if (m) return await songAction(req, res, m[1], m[2]);
    if (GET && p === '/api/ir/info') return send(res, 200, { hash: configHash() });
    if (GET && p === '/api/agent') {
      return send(res, 200, { online: agentOnline(), apiVersion: agentApiVersion, pending: pendingApi.size, remembered: agentCache.size, lastError: agentLastError, lastTiming: agentLastTiming });
    }
    if (GET && p === '/api/ir/styles') return send(res, 200, { items: availableStyles() });
    if (GET && p === '/api/ir/bases') return send(res, 200, { items: availableBases() });
    m = /^\/api\/ir\/custom\/([LR])\.wav$/.exec(p);
    if (GET && m) {
      let custom;
      try { custom = await getCustomIr(url.searchParams); } catch (e) { return send(res, 404, { error: String(e.message || e) }); }
      return send(res, 200, custom[m[1]], 'audio/wav');
    }
    if (GET && p === '/api/ir/height-curves') {
      const freqs = [250, 500, 1000, 2000, 3000, 4000, 5000, 6000, 7000, 8000, 9000, 10000, 11000, 12000, 14000, 16000];
      const db = (v) => Math.round(200 * Math.log10(Math.max(v, 1e-6))) / 10;
      const cue = loadKemarCue();
      return send(res, 200, { freqs, synthetic: freqs.map((f) => db(heightCurve(f))), measuredNear: freqs.map((f) => db(cue.near(f))), measuredFar: freqs.map((f) => db(cue.far(f))) });
    }
    m = /^\/api\/ir\/band\/(drums|bass|other|vocals)\/([LR])\.wav$/.exec(p);
    if (GET && m) {
      let irs;
      try { irs = await getBandIr(m[1], url.searchParams); } catch (e) { return send(res, 404, { error: String(e.message || e) }); }
      return send(res, 200, irs[m[2]], 'audio/wav');
    }
    m = /^\/api\/ir\/([\w-]{1,32})\/([LR])\.wav$/.exec(p);
    if (GET && m) {
      let ir;
      try { ir = await getStyleIr(m[1]); } catch (e) { return send(res, 404, { error: String(e.message || e) }); }
      return send(res, 200, ir[m[2]], 'audio/wav');
    }
    m = /^\/api\/ir\/([LR])\.wav$/.exec(p);
    if (GET && m) {
      const ir = await getIr();
      return send(res, 200, ir[m[1]], 'audio/wav');
    }
    if (GET && p === '/api/home') {
      // c = continuation token from a previous page: the feed is endless, like the real home screen.
      const c = url.searchParams.get('c') || '';
      if (c && !/^[\w%-]{10,2000}$/.test(c)) return send(res, 400, { error: 'bad continuation' });
      const queryFor = (t) => 'ctoken=' + encodeURIComponent(t) + '&continuation=' + encodeURIComponent(t) + '&type=next';
      const query = c ? queryFor(c) : '';
      // The token is sent both ways YouTube Music has accepted it (request body and query string).
      const wantFresh = url.searchParams.get('fresh') === '1';
      // p = the parameter of a filter chip
      const chip = url.searchParams.get('p') || '';
      if (chip && !/^[\w%-]{4,400}$/.test(chip)) return send(res, 400, { error: 'bad filter' });
      const firstPage = chip ? { browseId: 'FEmusic_home', params: chip } : { browseId: 'FEmusic_home' };
      homeAskedAt = Date.now();
      const r = await ytApiPersonal('browse', c ? { continuation: c } : firstPage, query, c || chip ? 25000 : (wantFresh ? 3000 : 5000), wantFresh);
      const next = findContinuation(r.json);
      // The tab is slow to answer, so the following page is requested now and is ready when scrolled to.
      if (next && r.personalized && agentUsable() && !agentCache.has(agentKey('browse', { continuation: next }, queryFor(next)))) {
        agentApi('browse', { continuation: next }, queryFor(next)).catch(() => {});
      }
      return send(res, 200, { personalized: r.personalized, sections: parseSections(r.json), next, chips: c ? [] : parseChips(r.json) });
    }
    if (GET && p === '/api/search') {
      const q = (url.searchParams.get('q') || '').trim();
      if (!q) return send(res, 400, { error: 'empty query' });
      const r = await ytApi('search', { query: q });
      return send(res, 200, { sections: parseSections(r.json) });
    }
    if (GET && p === '/api/browse') {
      const id = url.searchParams.get('id') || '';
      if (!/^[\w-]{2,80}$/.test(id)) return send(res, 400, { error: 'bad id' });
      let r = await ytApi('browse', { browseId: id });
      let out = Object.assign(parseHeader(r.json), { sections: parseSections(r.json) });
      // Private pages (liked songs, own playlists) come back empty without the signed-in account.
      if (!out.sections.length && agentUsable()) {
        r = await ytApiPersonal('browse', { browseId: id }, '', 25000);
        out = Object.assign(parseHeader(r.json), { sections: parseSections(r.json) });
      }
      // Radio mixes have no browse page; show their queue as a track list instead.
      if (!out.sections.length && id.startsWith('VL')) {
        const items = (await getQueue('', id.slice(2))).items;
        if (items.length) out.sections.push({ title: '', items });
      }
      return send(res, 200, out);
    }
    m = /^\/api\/song\/([\w-]{11})\/(info|lyrics)$/.exec(p);
    if (GET && m) {
      if (m[2] === 'lyrics') return send(res, 200, await getLyrics(m[1]));
      const info = await getSongInfo(m[1]);
      return send(res, 200, { runs: info.runs, hasLyrics: !!info.lyricsId });
    }
    m = /^\/api\/mix\/([\w-]{11})(\/intro\.m4a)?$/.exec(p);
    if (GET && m) {
      if (m[2]) {
        await ensureIntro(m[1]);
        return serveFile(req, res, introPath(m[1]), 'audio/mp4');
      }
      return send(res, 200, await getMixInfo(m[1]));
    }
    m = /^\/api\/env\/([\w-]{11})$/.exec(p);
    if (GET && m) return serveFile(req, res, await ensureEnv(m[1]), 'application/octet-stream');
    if (POST && p === '/api/debug') {
      debugWrite(await readBody(req, 2e6));
      return send(res, 200, { ok: true });
    }
    if (GET && p === '/api/diag') {
      console.log(new Date().toTimeString().slice(0, 8) + ' diag ' + String(url.search).slice(0, 120).replace(/[^\w=&?.-]/g, ''));
      return send(res, 200, { ok: true });
    }
    if (GET && p === '/api/queue') {
      const videoId = url.searchParams.get('videoId') || '';
      const playlistId = url.searchParams.get('playlistId') || '';
      /* c = the continuation of a radio that was started: the next part of it */
      const more = url.searchParams.get('c') || '';
      if (more) {
        if (!/^[\w%=-]{10,4000}$/.test(more)) return send(res, 400, { error: 'bad continuation' });
        return send(res, 200, await getQueueMore(more));
      }
      if (videoId && !ID_RE.test(videoId)) return send(res, 400, { error: 'bad videoId' });
      if (playlistId && !/^[\w-]{2,80}$/.test(playlistId)) return send(res, 400, { error: 'bad playlistId' });
      if (!videoId && !playlistId) return send(res, 400, { error: 'videoId or playlistId required' });
      return send(res, 200, await getQueue(videoId, playlistId));
    }
  } catch (e) {
    return send(res, 502, { error: String(e.message || e) });
  }

  // Agent endpoints: only the userscript on this machine may call them.
  if (p.startsWith('/agent/')) {
    if (!isLoopback(req)) return send(res, 403, { error: 'forbidden' });
    agentSeen = Date.now();
    if (POST && p === '/agent/state') { await readBody(req); if (process.env.YTM_DEBUG) console.log(new Date().toISOString().slice(11, 23) + ' state'); return send(res, 200, { ok: true }); }
    if (POST && p === '/agent/result') {
      const b = await readBody(req, 2e7);
      const pend = b && pendingApi.get(b.rid);
      if (pend) {
        pendingApi.delete(b.rid);
        clearTimeout(pend.timer);
        if (b.ok && b.json) { agentLastError = ''; agentLastTiming = { fetchMs: b.fetchMs, totalMs: Date.now() - pend.sentAt, hidden: b.hidden }; pend.resolve(b.json); } else { agentLastError = String((b && b.error) || 'agent request failed'); pend.reject(new Error(agentLastError)); }
      }
      return send(res, 200, { ok: true });
    }
    if (GET && p === '/agent/poll') {
      agentApiVersion = Number(url.searchParams.get('api')) || 0;
      if (process.env.YTM_DEBUG) console.log(new Date().toISOString().slice(11, 23) + ' poll v' + agentApiVersion + ' queued=' + queue.length);
      agentHasApi = agentApiVersion >= 1;
      if (queue.length) return send(res, 200, queue.splice(0));
      if (waiter) { clearTimeout(waiter.timer); send(waiter.res, 200, []); }
      const w = { res, timer: setTimeout(() => { if (waiter === w) waiter = null; send(res, 200, []); }, 20000) };
      waiter = w;
      req.on('close', () => { if (waiter === w) { clearTimeout(w.timer); waiter = null; } });
      return;
    }
  }
  send(res, 404, { error: 'not found' });
}

function onRequest(req, res) {
  handle(req, res).catch((e) => { if (!res.headersSent) send(res, 500, { error: String(e.message || e) }); else res.destroy(); });
}

// Listen on loopback (userscript) and on the Tailscale address (phone) only, never on the LAN.
const hosts = ['127.0.0.1'];
for (const list of Object.values(os.networkInterfaces())) {
  for (const i of list || []) if (i.family === 'IPv4' && i.address.startsWith('100.')) hosts.push(i.address);
}
fs.mkdirSync(CACHE_ROOT, { recursive: true });
for (const h of hosts) http.createServer(onRequest).listen(PORT, h, () => console.log('listening on http://' + h + ':' + PORT));
console.log('cache: ' + CACHE_ROOT + '   config: ' + configHash() + '   yt-dlp: ' + YTDLP);


/* ================================================================ standalone overrides
   Appended by build-app.js in the same scope as the code of server.js above.

   In the app this copy of the server code is the FALLBACK: normally the page's requests go to the
   user's own PC (see standalone.js). It answers by itself only what needs no PC - the surround
   impulse responses - and, while the PC cannot be reached, the anonymous search / home / browse /
   queue. It never fetches audio: songs come from the PC, or from files stored in the app. */

const SA_NO_PC = '連不到電腦';
const saNeedsPc = (what) => () => Promise.reject(new Error(SA_NO_PC + '：' + what + '需要電腦'));

/* Everything that needs yt-dlp, ffmpeg or Equalizer APO fails at once with a clear reason. */
