ensureIntro = saNeedsPc('自動混音');
ensureEnv = saNeedsPc('背景律動資料');
ensureFx = saNeedsPc('電腦端音效處理');
ensureRaw = saNeedsPc('電腦端快取');
ensureProcessed = saNeedsPc('電腦端處理');
getIr = saNeedsPc('目前的 HeSuVi 設定');

/* Liking and saving go through the PC's signed-in browser tab. */
const saSongAction = songAction;
songAction = async function (req, res, videoId, what) {
  if (what === 'comments') return saSongAction(req, res, videoId, what);
  return send(res, 503, { error: SA_NO_PC + '，這個功能需要電腦' });
};

/* ---------------------------------------------------------------- where the PC is */
const SA_PC_DEFAULT = 'http://127.0.0.1:8787';
/* An http(s) address with nothing after the host (and port): 'http://127.0.0.1:8787'. */
backend.pcValid = function (text) {
  const s = String(text || '').trim().replace(/\/+$/, '');
  if (!/^https?:\/\/[A-Za-z0-9.-]+(:\d{1,5})?$/.test(s) && !/^https?:\/\/\[[0-9A-Fa-f:]+\](:\d{1,5})?$/.test(s)) return '';
  return s;
};
backend.pcDefault = SA_PC_DEFAULT;
backend.pcBase = function () {
  let saved = '';
  try { saved = G.localStorage.getItem('ytm_pc') || ''; } catch (e) { saved = ''; }
  return backend.pcValid(saved) || SA_PC_DEFAULT;
};

/* Where a song is played from: the plain file on the PC (the app's own engine does the sound).
   hint = the length the caller already knows (seconds), used when the PC does not say. */
backend.mediaUrl = function (id) { return backend.pcBase() + '/media/' + id + '.m4a?mode=phone'; };
backend.stream = function (id, hint) {
  if (!ID_RE.test(String(id))) return Promise.reject(new Error('bad videoId'));
  const out = { url: backend.mediaUrl(id), headers: {}, size: 0, durationSec: Number(hint) > 0 ? Number(hint) : 0, mime: 'audio/mp4' };
  return bridgeHttp({ url: backend.pcBase() + '/api/track/' + id + '/status?mode=phone', method: 'GET', headers: {}, body: null, timeoutMs: 4000 }).then((r) => {
    try {
      const j = JSON.parse(Buffer.from(r.body || '', 'base64').toString('utf8'));
      if (r.status === 200 && j && j.duration > 0) out.durationSec = j.duration;
    } catch (e) { /* the length stays what the caller knew */ }
    return out;
  }, () => out);
};

